package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

const (
	modulePath       = "github.com/Aaditya07124063/logstonedb"
	raftImportPath   = modulePath + "/internal/raft"
	simulationImport = modulePath + "/internal/simulation"
)

func main() {
	root := flag.String("root", ".", "repository root to check")
	flag.Parse()

	if err := checkRoot(*root); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println("raft boundaries verified")
}

func checkRoot(root string) error {
	var problems []string
	problems = append(problems, checkPackage(filepath.Join(root, "internal", "raft"), true)...)
	problems = append(problems, checkPackage(filepath.Join(root, "internal", "simulation"), false)...)
	if len(problems) == 0 {
		return nil
	}
	return fmt.Errorf("raft boundary check failed:\n%s", strings.Join(problems, "\n"))
}

func checkPackage(dir string, raft bool) []string {
	files, err := goFiles(dir)
	if err != nil {
		return []string{err.Error()}
	}

	var problems []string
	fset := token.NewFileSet()
	for _, name := range files {
		file, parseErr := parser.ParseFile(fset, name, nil, parser.AllErrors)
		if parseErr != nil {
			problems = append(problems, fmt.Sprintf("%s: parse error: %v", name, parseErr))
			continue
		}

		isTest := strings.HasSuffix(name, "_test.go")
		for _, spec := range file.Imports {
			path, unquoteErr := strconv.Unquote(spec.Path.Value)
			if unquoteErr != nil {
				problems = append(problems, fmt.Sprintf("%s: invalid import %q: %v", name, spec.Path.Value, unquoteErr))
				continue
			}
			if reason := importViolation(path, isTest, raft); reason != "" {
				problems = append(problems, fmt.Sprintf("%s: %s", name, reason))
			}
		}

		if raft {
			ast.Inspect(file, func(node ast.Node) bool {
				if _, ok := node.(*ast.GoStmt); ok {
					problems = append(problems, fmt.Sprintf("%s: goroutine statement is forbidden", name))
				}
				return true
			})
		}
	}
	return problems
}

func goFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", dir, err)
	}

	var files []string
	for _, entry := range entries {
		name := filepath.Join(dir, entry.Name())
		if entry.IsDir() {
			childFiles, childErr := goFiles(name)
			if childErr != nil {
				return nil, childErr
			}
			files = append(files, childFiles...)
			continue
		}
		if entry.Type().IsRegular() && strings.HasSuffix(entry.Name(), ".go") {
			files = append(files, name)
		}
	}
	sort.Strings(files)
	return files, nil
}

func importViolation(path string, isTest, raft bool) string {
	if raft {
		if isForbiddenRaftImport(path) {
			return fmt.Sprintf("forbidden import %q", path)
		}
		if path == simulationImport || path == "internal/simulation" {
			return "internal/raft must not import internal/simulation"
		}
	}

	if !isStandardLibrary(path) {
		if !raft && (path == raftImportPath || path == "internal/raft") {
			return ""
		}
		return fmt.Sprintf("non-standard-library import %q", path)
	}

	if isTest && path == "testing" {
		return ""
	}
	return ""
}

func isForbiddenRaftImport(path string) bool {
	if path == "time" || path == "os" || path == "net" || path == "io/fs" ||
		path == "io/ioutil" || path == "syscall" || path == "sync" ||
		path == "math/rand" || path == "math/rand/v2" || path == "crypto/rand" ||
		path == "log" {
		return true
	}
	return strings.HasPrefix(path, "os/") || strings.HasPrefix(path, "net/") ||
		strings.HasPrefix(path, "sync/")
}

func isStandardLibrary(path string) bool {
	pkg, err := build.Default.Import(path, "", build.FindOnly)
	return err == nil && pkg.Goroot
}
